mapper.select:
SELECT c.id, c.user_id AS customerId, c.product_id AS productId, p.`name` AS productName, p.price AS productPrice, p.main_image AS productMainImage, c.quantity, c.is_checked AS checked FROM `shopping_cart` AS c INNER JOIN product AS p ON c.product_id = p.id
AND c.user_id = #{customerId}
AND c.is_checked = #{isChecked}
AND c.is_deleted = 0 AND p.is_deleted = 0
